From 74be16ef486d71182964c91ceab14005c845dcc6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:45:32 +0100
Subject: [PATCH] libtaskmanager: keep the manual order of grouped tasks

When tasks got grouped in manual sort mode, their sort map entries were
rearranged in the order of the grouping model, so their custom order was
lost once ungrouped. Now the group's tasks keep their existing order.

BUG: 424836
---
 libtaskmanager/tasksmodel.cpp | 77 +++++++++++++++++++++++------------
 1 file changed, 52 insertions(+), 25 deletions(-)

diff --git a/libtaskmanager/tasksmodel.cpp b/libtaskmanager/tasksmodel.cpp
index fd6246a363..1bd9c75744 100644
--- a/libtaskmanager/tasksmodel.cpp
+++ b/libtaskmanager/tasksmodel.cpp
@@ -77,7 +77,8 @@ public:
     void initLauncherTasksModel();
     void updateAnyTaskDemandsAttention();
     void updateManualSortMap();
-    void consolidateManualSortMapForGroup(const QModelIndex &groupingProxyIndex);
+    QList<int> manualSortMapRowsForGroup(const QModelIndex &groupingProxyIndex) const;
+    void consolidateManualSortMapForGroup(const QModelIndex &groupingProxyIndex, QList<int> rows = {});
     void updateGroupInline();
     void updateActiveTask();
     QModelIndex preFilterIndex(const QModelIndex &sourceIndex) const;
@@ -530,29 +531,56 @@ void TasksModel::Private::updateManualSortMap()
     }
 }

-void TasksModel::Private::consolidateManualSortMapForGroup(const QModelIndex &groupingProxyIndex)
+QList<int> TasksModel::Private::manualSortMapRowsForGroup(const QModelIndex &groupingProxyIndex) const
 {
-    // Consolidates sort map entries for a group's items to be contiguous
-    // after the group's first item and the same order as in groupingProxyModel.
+    // Returns the pre-filter rows of a group's items in sort map order, or in
+    // groupingProxyModel order in inline grouping mode.
+
+    QList<int> rows;
+
+    for (int i = 0; i < groupingProxyModel->rowCount(groupingProxyIndex); ++i) {
+        const QModelIndex &child = groupingProxyModel->index(i, 0, groupingProxyIndex);
+        rows << filterProxyModel->mapToSource(groupingProxyModel->mapToSource(child)).row();
+    }

-    const int childCount = groupingProxyModel->rowCount(groupingProxyIndex);
+    if (!flattenGroupsProxyModel) {
+        std::ranges::sort(rows, [this](int left, int right) {
+            return sortedPreFilterRows.indexOf(left) < sortedPreFilterRows.indexOf(right);
+        });
+    }
+
+    return rows;
+}
+
+void TasksModel::Private::consolidateManualSortMapForGroup(const QModelIndex &groupingProxyIndex, QList<int> rows)
+{
+    // Consolidates sort map entries for a group's items to be contiguous
+    // around the group's first item, in the given order or else the order
+    // from manualSortMapRowsForGroup().

-    if (!childCount) {
+    if (groupingProxyModel->rowCount(groupingProxyIndex) < 2) {
         return;
     }

+    if (rows.isEmpty()) {
+        rows = manualSortMapRowsForGroup(groupingProxyIndex);
+    }
+
     const QModelIndex &leader = groupingProxyModel->index(0, 0, groupingProxyIndex);
-    const QModelIndex &preFilterLeader = filterProxyModel->mapToSource(groupingProxyModel->mapToSource(leader));
+    const int preFilterLeaderRow = filterProxyModel->mapToSource(groupingProxyModel->mapToSource(leader)).row();

-    // We're moving the trailing children to the sort map position of
-    // the first child, so we're skipping the first child.
-    for (int i = 1; i < childCount; ++i) {
-        const QModelIndex &child = groupingProxyModel->index(i, 0, groupingProxyIndex);
-        const QModelIndex &preFilterChild = filterProxyModel->mapToSource(groupingProxyModel->mapToSource(child));
-        const int leaderPos = sortedPreFilterRows.indexOf(preFilterLeader.row());
-        const int childPos = sortedPreFilterRows.indexOf(preFilterChild.row());
-        const int insertPos = (leaderPos + i) + ((leaderPos + i) > childPos ? -1 : 0);
-        sortedPreFilterRows.move(childPos, insertPos);
+    for (const int row : std::as_const(rows)) {
+        if (row != preFilterLeaderRow) {
+            sortedPreFilterRows.removeOne(row);
+        }
+    }
+
+    // The group keeps the sort map position of its first item.
+    const int insertPos = sortedPreFilterRows.indexOf(preFilterLeaderRow);
+    sortedPreFilterRows.removeAt(insertPos);
+
+    for (int i = 0; i < rows.count(); ++i) {
+        sortedPreFilterRows.insert(insertPos + i, rows.at(i));
     }
 }

@@ -1741,6 +1769,9 @@ bool TasksModel::move(int row, int newPos, const QModelIndex &parent)
             }
         }

+        // Moving a group parent only moves its first item in the sort map.
+        const QList<int> groupRows = groupNotDisabled ? d->manualSortMapRowsForGroup(groupingRowIndex) : QList<int>();
+
         row = d->sortedPreFilterRows.indexOf(preFilterRowIndex.row());
         newPos = d->sortedPreFilterRows.indexOf(d->preFilterIndex(mapToSource(index(newPos, 0, parent))).row());

@@ -1752,21 +1783,17 @@ bool TasksModel::move(int row, int newPos, const QModelIndex &parent)
         // If we moved a group parent, consolidate sort map for children.
         if (groupNotDisabled) {
             if (d->groupingProxyModel->rowCount(groupingRowIndex)) {
-                d->consolidateManualSortMapForGroup(groupingRowIndex);
+                d->consolidateManualSortMapForGroup(groupingRowIndex, groupRows);
             }
             // Special case: Before moving, the task at newPos is a group parent
             // Before moving: [Task] [Group parent] [Other task in group]
             // After moving: [Group parent (not consolidated yet)] [Task, newPos] [Other task in group]
-            if (int childCount = d->groupingProxyModel->rowCount(adjacentGroupingRowIndex); childCount && adjacentGroupingRowIndex.isValid()) {
+            // After consolidation: [Group parent] [Other task in group] [Task]
+            if (d->groupingProxyModel->rowCount(adjacentGroupingRowIndex) && adjacentGroupingRowIndex.isValid()) {
                 d->consolidateManualSortMapForGroup(adjacentGroupingRowIndex);
-                if (newPos > row) {
-                    newPos += childCount - 1;
-                    // After consolidation: [Group parent (not consolidated yet)] [Other task in group] [Task, newPos]
-                }
-                // No need to consider newPos < row
-                // Before moving: [Group parent, newPos] [Other task in group] [Task]
-                // After moving: [Task, newPos] [Group parent] [Other task in group]
             }
+
+            newPos = d->sortedPreFilterRows.indexOf(preFilterRowIndex.row());
         }
     }

